{
  "correction_rules": [
    "Bias correction: Model consistently overestimates prices; reduce forecast by 1-3% for short-term (1-7d) and 3-5% for medium-term (8-30d) horizons.",
    "Lag correction: Forecast tends to lag true price movements by 1-3 days; adjust for recent sentiment shifts (especially +0.50 or -0.25) to anticipate 1-2 day price reversals.",
    "Overshoot after spikes: After price spikes (e.g., >70), model overcorrects downward; reduce forecast by 2-5% for 3-5 day windows post-spike.",
    "Mean reversion: Model underestimates mean reversion in 10-14 day windows; apply upward bias of 1-3% if sentiment is neutral or slightly positive.",
    "Sentiment-driven adjustment: If sentiment > 0.00, increase forecast by 0.5-1.5% for 1-3 day horizon; if sentiment < 0.00, reduce by 0.5-1.5% for 1-3 day horizon."
  ]
}
